import { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { updateUserProfile, deleteUserAccount } from '../../services/api.js';

function getAuthUser() {
  const raw = localStorage.getItem('authUser');
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export default function StaffProfile() {
  const navigate = useNavigate();
  const currentUser = getAuthUser();

  const [name, setName] = useState(currentUser?.name || '');
  const [email, setEmail] = useState(currentUser?.email || '');
  const [password, setPassword] = useState('');
  const [status, setStatus] = useState('');
  const [error, setError] = useState('');

  if (!currentUser) {
    navigate('/login');
    return null;
  }

  const handleLogout = () => {
    localStorage.removeItem('authUser');
    navigate('/login');
  };

  const handleSave = async (event) => {
    event.preventDefault();
    setError('');
    setStatus('');

    try {
      const payload = { name, email };
      if (password) payload.password = password;

      const data = await updateUserProfile(payload, currentUser.token);
      localStorage.setItem('authUser', JSON.stringify({ ...currentUser, ...data, token: currentUser.token }));
      setStatus('Profile updated successfully');
      setPassword('');
    } catch (err) {
      setError(err.message || 'Profile update failed');
    }
  };

  const handleDelete = async () => {
    const confirmed = window.confirm('Delete your account? This cannot be undone.');
    if (!confirmed) return;

    try {
      await deleteUserAccount({}, currentUser.token);
      localStorage.removeItem('authUser');
      navigate('/login');
    } catch (err) {
      setError(err.message || 'Account deletion failed');
    }
  };

  return (
    <main className="auth-page">
      <section className="auth-card">
        <header>
          <h1>Welcome, {currentUser.name}</h1>
          <p>Your account role is {currentUser.role}.</p>
        </header>

        <form onSubmit={handleSave} className="auth-form">
          <label>
            Full Name
            <input value={name} onChange={(event) => setName(event.target.value)} required />
          </label>
          <label>
            Email
            <input type="email" value={email} onChange={(event) => setEmail(event.target.value)} required />
          </label>
          <label>
            New Password
            <input type="password" value={password} onChange={(event) => setPassword(event.target.value)} />
          </label>
          {error && <p className="auth-error-text">{error}</p>}
          {status && <p className="auth-success-text">{status}</p>}
          <button type="submit" className="auth-button">Save Profile</button>
        </form>

        <div className="auth-actions">
          <button className="auth-button auth-button-secondary" onClick={handleLogout}>Logout</button>
          <button className="auth-button auth-button-danger" onClick={handleDelete}>Delete Account</button>
        </div>
        {currentUser.role === 'staff' && (
          <p className="auth-small-note">
            <Link to="/staff">Manage participants</Link>
          </p>
        )}
      </section>
    </main>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authLogin } from '../../services/api.js';

export default function Login() {
  const navigate = useNavigate();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');
    try {
      const data = await authLogin({ email, password });
      localStorage.setItem('authUser', JSON.stringify(data));
      navigate('/');
    } catch (err) {
      setError(err.message || 'Unable to login');
    }
  };

  return (
    <main className="auth-page">
      <section className="auth-card">
        <h1>Login</h1>
        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            Email
            <input
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              required
            />
          </label>
          <label>
            Password
            <input
              type="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              required
            />
          </label>
          {error && <p className="auth-error-text">{error}</p>}
          <button className="auth-button" type="submit">Login</button>
        </form>
        <p className="auth-small-note">
          Don't have an account? <a href="/signup">Sign up</a>
        </p>
      </section>
    </main>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { authSignup } from '../../services/api.js';

export default function Signup() {
  const navigate = useNavigate();
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();
    setError('');
    setMessage('');
    try {
      await authSignup({ name, email, password });
      setMessage('Account created. Redirecting to login...');
      setTimeout(() => navigate('/login'), 1000);
    } catch (err) {
      setError(err.message || 'Signup failed');
    }
  };

  return (
    <main className="auth-page">
      <section className="auth-card">
        <h1>Staff Sign Up</h1>
        <p className="auth-small-note">Create a staff account to manage the application</p>
        <form onSubmit={handleSubmit} className="auth-form">
          <label>
            Full Name
            <input
              value={name}
              onChange={(event) => setName(event.target.value)}
              required
            />
          </label>
          <label>
            Email
            <input
              type="email"
              value={email}
              onChange={(event) => setEmail(event.target.value)}
              required
            />
          </label>
          <label>
            Password
            <input
              type="password"
              value={password}
              onChange={(event) => setPassword(event.target.value)}
              required
            />
          </label>
          {error && <p className="auth-error-text">{error}</p>}
          {message && <p className="auth-success-text">{message}</p>}
          <button className="auth-button" type="submit">Sign Up</button>
        </form>
        <p className="auth-small-note">
          Already have an account? <a href="/login">Login</a>
        </p>
      </section>
    </main>
  );
}

import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { getAllUsers, createUserAccount, updateUserProfile, deleteUserAccount } from '../../services/api.js';

function getAuthUser() {
  const raw = localStorage.getItem('authUser');
  if (!raw) return null;
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

const emptyForm = { name: '', email: '', password: '', role: 'participant' };

export default function ParticipantManagement() {
  const navigate = useNavigate();
  const currentUser = getAuthUser();

  const [accounts, setAccounts] = useState([]);
  const [selected, setSelected] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [error, setError] = useState('');
  const [status, setStatus] = useState('');

  if (!currentUser) {
    navigate('/login');
    return null;
  }
  if (currentUser.role !== 'staff') {
    navigate('/profile');
    return null;
  }

  useEffect(() => {
    fetchAccounts();
  }, []);

  const fetchAccounts = async () => {
    try {
      const data = await getAllUsers(currentUser.token);
      setAccounts(data);
    } catch (err) {
      setError(err.message || 'Unable to load accounts');
    }
  };

  const handleCreate = async (event) => {
    event.preventDefault();
    setError('');
    setStatus('');

    try {
      await createUserAccount(form, currentUser.token);
      setStatus('Account created successfully');
      setForm(emptyForm);
      fetchAccounts();
    } catch (err) {
      setError(err.message || 'Create account failed');
    }
  };

  const handleSelect = (account) => {
    setSelected(account);
    setForm({
      name: account.name || '',
      email: account.email || '',
      password: '',
      role: account.role || 'participant',
    });
    setStatus('Editing ' + account.name);
    setError('');
  };

  const handleUpdate = async (event) => {
    event.preventDefault();
    if (!selected) return;
    setError('');
    setStatus('');

    try {
      const payload = { targetId: selected.id, name: form.name, email: form.email, role: form.role };
      if (form.password) payload.password = form.password;

      await updateUserProfile(payload, currentUser.token);
      setStatus('Account updated successfully');
      setSelected(null);
      setForm(emptyForm);
      fetchAccounts();
    } catch (err) {
      setError(err.message || 'Update failed');
    }
  };

  const handleDelete = async (accountId) => {
    const confirmed = window.confirm('Delete this account?');
    if (!confirmed) return;
    setError('');
    setStatus('');

    try {
      await deleteUserAccount({ targetId: accountId }, currentUser.token);
      setStatus('Account deleted successfully');
      if (selected?.id === accountId) {
        setSelected(null);
        setForm(emptyForm);
      }
      fetchAccounts();
    } catch (err) {
      setError(err.message || 'Delete failed');
    }
  };

  const handleCancelEdit = () => {
    setSelected(null);
    setForm(emptyForm);
    setStatus('');
    setError('');
  };

  return (
    <main className="staff-mgmt-page">
      <header className="staff-mgmt-header">
        <h1>Participant Management</h1>
        <p>Welcome back, {currentUser.name}. Manage participant and staff accounts below.</p>
      </header>

      {error && <p className="auth-error-text">{error}</p>}
      {status && <p className="auth-success-text">{status}</p>}

      <div className="staff-mgmt-grid">
        <section className="staff-mgmt-panel staff-mgmt-panel-main">
          <h2>Accounts</h2>
          {accounts.length === 0 ? (
            <p className="auth-small-note">No accounts yet.</p>
          ) : (
            <table className="staff-table">
              <thead>
                <tr>
                  <th>Name</th>
                  <th>Email</th>
                  <th>Role</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {accounts.map((account) => (
                  <tr key={account.id}>
                    <td>{account.name}</td>
                    <td>{account.email}</td>
                    <td>{account.role}</td>
                    <td>
                      <button className="auth-button auth-button-secondary" type="button" onClick={() => handleSelect(account)}>
                        Edit
                      </button>
                      <button className="auth-button auth-button-danger" type="button" onClick={() => handleDelete(account.id)}>
                        Delete
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>

        <section className="staff-mgmt-panel staff-mgmt-panel-form">
          <h2>{selected ? 'Edit Account' : 'Create Account'}</h2>
          <form onSubmit={selected ? handleUpdate : handleCreate} className="auth-form">
            <label>
              Full Name
              <input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required />
            </label>
            <label>
              Email
              <input type="email" value={form.email} onChange={(event) => setForm({ ...form, email: event.target.value })} required />
            </label>
            <label>
              Password
              <input
                type="password"
                value={form.password}
                onChange={(event) => setForm({ ...form, password: event.target.value })}
                placeholder={selected ? 'Leave blank to keep current password' : ''}
                required={!selected}
              />
            </label>
            <label>
              Role
              <select value={form.role} onChange={(event) => setForm({ ...form, role: event.target.value })}>
                <option value="participant">Participant</option>
                <option value="staff">Staff</option>
              </select>
            </label>
            <button className="auth-button" type="submit">
              {selected ? 'Update Account' : 'Create Account'}
            </button>
            {selected && (
              <button type="button" className="auth-button auth-button-secondary" onClick={handleCancelEdit}>
                Cancel
              </button>
            )}
          </form>
        </section>
      </div>
    </main>
  );
}

