            id: created.id,
            name: created.enName,
            email: created.email,
            role: created.role,
        });
    } catch (err) {
        console.error('Signup error:', err);
        return res.status(500).json({ error: 'Signup failed: ' + (err.message || err.toString()) });
    }
});

